using MiniStore.Application.DTOs.Purchases;using MiniStore.Domain.Entities;using MiniStore.Domain.Interfaces;
namespace MiniStore.Application.Services;
public sealed class LandedCostService(ILandedCostRepository costs,IGoodsReceiptRepository receipts,IPurchaseOrderRepository orders,ISupplierRepository suppliers,IWarehouseRepository warehouses,IProductStockRepository stocks,IStockTransactionRepository transactions,IAccountingSettingsRepository accountingSettings,DocumentNumberService numbers,JournalPostingService journalPosting,IUnitOfWork unitOfWork,ICurrentUserService currentUser)
{
 public async Task<LandedCostCreatePageDto>GetCreatePageAsync(int receiptId,CreateLandedCostDto?form=null)
 {
  var receipt=await receipts.GetByIdAsync(receiptId);if(receipt is null)return new(){Form=form??NewForm(receiptId)};var order=await orders.GetByIdAsync(receipt.PurchaseOrderId);return new(){Form=form??NewForm(receiptId),ReceiptNumber=receipt.ReceiptNumber,OrderNumber=order?.OrderNumber??"-",SupplierName=order is null?"-":(await suppliers.GetByIdAsync(order.SupplierId))?.Name??"-",WarehouseName=(await warehouses.GetByIdAsync(receipt.WarehouseId))?.Name??"-",Lines=receipt.Lines.Select(x=>new LandedCostReceiptLineDto{Product=$"{x.ProductCodeSnapshot} — {x.ProductNameSnapshot}",Quantity=x.StockQuantity,ReceiptValue=Round(x.ReceivedQuantity*x.UnitCost)}).ToList()};
 }
 public async Task<List<LandedCostDto>>GetAllAsync(){var rs=(await receipts.GetAllAsync(null)).ToDictionary(x=>x.Id,x=>x.ReceiptNumber);var ws=(await warehouses.GetAllAsync()).ToDictionary(x=>x.Id,x=>x.Name);return(await costs.GetAllAsync()).Select(x=>Map(x,rs.GetValueOrDefault(x.GoodsReceiptId,"-"),ws.GetValueOrDefault(x.WarehouseId,"-"))).ToList();}
 public async Task<LandedCostDto?>GetAsync(int id){var x=await costs.GetByIdAsync(id);if(x is null)return null;return Map(x,(await receipts.GetByIdAsync(x.GoodsReceiptId))?.ReceiptNumber??"-",(await warehouses.GetByIdAsync(x.WarehouseId))?.Name??"-");}
 public async Task<int>CreateAndPostAsync(CreateLandedCostDto dto)
 {
  var components=dto.Components.Where(x=>x.Amount>0).ToList();if(components.Count==0)throw new ArgumentException("Enter at least one positive landed cost component.");if(components.GroupBy(x=>x.Type).Any(x=>x.Count()>1))throw new ArgumentException("Each landed cost type can appear only once per document.");LandedCost?created=null;
  await unitOfWork.ExecuteInTransactionAsync(async()=>
  {
   var receipt=await receipts.GetByIdAsync(dto.GoodsReceiptId)??throw new InvalidOperationException("Goods receipt was not found.");if(receipt.Status!=GoodsReceiptStatus.Posted)throw new InvalidOperationException("Landed costs require a posted goods receipt.");if(dto.CostDate<receipt.ReceiptDate)throw new ArgumentException("Landed cost date cannot be earlier than the goods receipt date.");var normalized=LandedCost.NormalizeReference(dto.ExternalReference);if(await costs.GetByExternalReferenceAsync(normalized)is not null)throw new InvalidOperationException("A landed cost with this external reference already exists.");
   var warehouse=await warehouses.GetByIdAsync(receipt.WarehouseId)??throw new InvalidOperationException("Receipt warehouse was not found.");if(!warehouse.InventoryAccountId.HasValue)throw new InvalidOperationException("Configure the receipt warehouse inventory account before posting landed costs.");var settings=await accountingSettings.GetAsync()??throw new InvalidOperationException("Configure accounting posting accounts before posting landed costs.");if(!settings.LandedCostClearingAccountId.HasValue)throw new InvalidOperationException("Configure a landed cost clearing account before posting landed costs.");
   created=new LandedCost(await numbers.GenerateAsync(DocumentNumberType.LandedCost,dto.CostDate.ToDateTime(TimeOnly.MinValue)),receipt.Id,receipt.WarehouseId,dto.CostDate,dto.ExternalReference,dto.AllocationMethod,dto.Notes,currentUser.UserId);foreach(var x in components)created.AddComponent(new LandedCostComponent(x.Type,x.Amount,x.Description));
   var basis=receipt.Lines.Select(x=>(line:x,value:dto.AllocationMethod==LandedCostAllocationMethod.ByQuantity?x.StockQuantity:Round(x.ReceivedQuantity*x.UnitCost))).Where(x=>x.value>0).ToList();if(basis.Count==0)throw new InvalidOperationException("The goods receipt has no positive allocation basis.");var totalBasis=basis.Sum(x=>x.value);var total=created.TotalAmount;var specs=new List<(GoodsReceiptLine line,decimal basis,decimal allocated,decimal capitalized,decimal expensed)>();var assigned=0m;var productReceiptQuantities=receipt.Lines.GroupBy(x=>x.ProductId).ToDictionary(x=>x.Key,x=>x.Sum(y=>y.StockQuantity));
   for(var i=0;i<basis.Count;i++){var allocated=i==basis.Count-1?total-assigned:Round(total*basis[i].value/totalBasis);assigned+=allocated;var stock=await stocks.GetByProductAndWarehouseAsync(basis[i].line.ProductId,receipt.WarehouseId);var ratio=stock is null||stock.Quantity<=0?0m:Math.Min(1m,stock.Quantity/productReceiptQuantities[basis[i].line.ProductId]);var capitalized=Round(allocated*ratio);specs.Add((basis[i].line,basis[i].value,allocated,capitalized,allocated-capitalized));}
   var movements=new Dictionary<int,InventoryCostMovement>();foreach(var group in specs.Where(x=>x.capitalized>0).GroupBy(x=>x.line.ProductId)){var stock=await stocks.GetByProductAndWarehouseAsync(group.Key,receipt.WarehouseId)??throw new InvalidOperationException("Received product stock was not found.");var movement=stock.AddLandedCost(group.Sum(x=>x.capitalized));movements[group.Key]=movement;await transactions.AddAsync(new StockTransaction(group.Key,receipt.WarehouseId,0,StockTransactionType.LandedCostAdjustment,created.CostNumber,movement));}
   foreach(var x in specs){movements.TryGetValue(x.line.ProductId,out var movement);created.AddAllocation(new LandedCostAllocation(x.line.Id,x.line.ProductId,x.basis,x.allocated,x.capitalized,x.expensed,movement?.AverageUnitCostBefore??0,movement?.AverageUnitCostAfter??0,x.line.ProductCodeSnapshot,x.line.ProductNameSnapshot));}created.EnsureBalanced();await costs.AddAsync(created);await unitOfWork.FlushAsync();
   var journal=new List<JournalEntryLine>();if(created.CapitalizedAmount>0)journal.Add(new JournalEntryLine(warehouse.InventoryAccountId.Value,created.CapitalizedAmount,0,warehouse.BranchId,warehouse.Id,created.CostNumber));if(created.ExpensedAmount>0){if(!settings.CostOfSalesAccountId.HasValue)throw new InvalidOperationException("Configure a cost of sales account before expensing consumed landed costs.");journal.Add(new JournalEntryLine(settings.CostOfSalesAccountId.Value,created.ExpensedAmount,0,warehouse.BranchId,warehouse.Id,created.CostNumber));}journal.Add(new JournalEntryLine(settings.LandedCostClearingAccountId.Value,0,total,null,null,created.CostNumber));await journalPosting.PostAsync(new JournalPostingRequest(dto.CostDate.ToDateTime(TimeOnly.MinValue),created.CostNumber,"LandedCost",created.CostNumber,journal,"This landed cost has already been posted to accounting."));
  });return created!.Id;
 }
 private static CreateLandedCostDto NewForm(int id)=>new(){GoodsReceiptId=id,Components=Enum.GetValues<LandedCostType>().Select(x=>new CreateLandedCostComponentDto{Type=x}).ToList()};
 private static LandedCostDto Map(LandedCost x,string receipt,string warehouse)=>new(){Id=x.Id,CostNumber=x.CostNumber,ReceiptNumber=receipt,WarehouseName=warehouse,CostDate=x.CostDate,Status=x.Status,ExternalReference=x.ExternalReference,AllocationMethod=x.AllocationMethod,TotalAmount=x.TotalAmount,CapitalizedAmount=x.CapitalizedAmount,ExpensedAmount=x.ExpensedAmount,Notes=x.Notes,Components=x.Components.Select(c=>new LandedCostComponentDto{Type=c.Type,Amount=c.Amount,Description=c.Description}).ToList(),Allocations=x.Allocations.Select(a=>new LandedCostAllocationDto{Product=$"{a.ProductCodeSnapshot} — {a.ProductNameSnapshot}",AllocationBasis=a.AllocationBasis,AllocatedAmount=a.AllocatedAmount,CapitalizedAmount=a.CapitalizedAmount,ExpensedAmount=a.ExpensedAmount,AverageUnitCostBefore=a.AverageUnitCostBefore,AverageUnitCostAfter=a.AverageUnitCostAfter}).ToList()};
 private static decimal Round(decimal value)=>Math.Round(value,2,MidpointRounding.AwayFromZero);
}
